import * as T from './vendor/three.module.js';
import {roundedBox} from './rounded-geometry.js';
import {packActor,restoreActor} from './actor-state.js';
import {steer} from './navigation.js';
import {statusStep,canSense} from './combat-rules.js';
export const BEAST_HP={wolf:105,hare:40,bear:260,werewolf:650};
const furTextures=new Map();
const names={wolf:'Лесной волк',hare:'Лесной кролик',bear:'Бурый медведь',werewolf:'Оборотень ночного тракта'};
export function beastModel(parent,species,x,z){
 const g=new T.Group();g.userData.dynamic=true;g.position.set(x,0,z);parent.add(g);const large=species==='bear',upright=species==='werewolf',rabbit=species==='hare',color=large?0x68513e:upright?0x343d48:rabbit?0x9d9182:0x6b7b80;
 const fur=new T.MeshStandardMaterial({color,roughness:1}),key=rabbit?'заяц_шерсть':'волк_шерсть';if(!furTextures.has(key))furTextures.set(key,new T.TextureLoader().loadAsync('./assets/'+key+'.webp'));furTextures.get(key).then(t=>{t.colorSpace=T.SRGBColorSpace;fur.map=t;fur.needsUpdate=true}).catch(()=>{});
 const dark=new T.MeshStandardMaterial({color:0x181b20}),eyes=new T.MeshBasicMaterial({color:upright?0xff733b:0xa9ca92});const part=(geo,m,x,y,z,p=g)=>{const o=new T.Mesh(geo,m);o.position.set(x,y,z);p.add(o);return o};const legs=[];let head;
 if(upright){part(roundedBox(.85,1.1,.5),fur,0,1.45,0);head=part(new T.SphereGeometry(.34,12,9),fur,0,2.18,.08);part(roundedBox(.35,.22,.43),fur,0,2.08,.35);for(const side of [-1,1]){const arm=new T.Group();arm.position.set(side*.54,1.85,0);g.add(arm);part(new T.CapsuleGeometry(.14,.6,3,7),fur,0,-.38,.1,arm);for(let i=0;i<3;i++)part(new T.ConeGeometry(.025,.24,5),dark,(i-1)*.085,-.81,.17,arm).rotation.x=.5;legs.push(arm);const leg=part(new T.CapsuleGeometry(.18,.7,3,8),fur,side*.25,.55,0);legs.push(leg)}}
 else{const body=part(new T.SphereGeometry(1,12,8),fur,0,rabbit?.35:large?1:.75,0);body.scale.set(rabbit?.32:large?.8:.45,rabbit?.3:large?.72:.4,rabbit?.5:large?1.1:.8);head=part(new T.SphereGeometry(rabbit?.23:large?.45:.3,12,9),fur,0,rabbit?.58:large?1.35:1.02,rabbit?.4:large?.9:.7);part(roundedBox(rabbit?.18:.32,rabbit?.12:.22,rabbit?.18:.4),fur,0,rabbit?.5:large?1.2:.93,rabbit?.57:large?1.25:.95);for(const side of [-1,1])for(const zz of [-1,1]){const leg=part(new T.CapsuleGeometry(rabbit?.07:large?.18:.1,rabbit?.13:large?.55:.4,3,7),fur,side*(rabbit?.19:large?.55:.28),rabbit?.16:large?.4:.32,zz*(rabbit?.23:large?.65:.5));legs.push(leg)}if(rabbit){for(const side of [-1,1]){const ear=part(new T.CapsuleGeometry(.06,.36,3,7),fur,side*.1,.95,.38);ear.rotation.z=side*.15}part(new T.SphereGeometry(.13,8,6),fur,0,.35,-.48)}}
 const y=upright?2.25:rabbit?.63:large?1.43:1.09,zz=upright?.35:rabbit?.57:large?1.23:.94;for(const side of [-1,1]){part(new T.SphereGeometry(.028,6,5),eyes,side*(rabbit?.1:.13),y,zz);if(!rabbit)part(large?new T.SphereGeometry(.13,8,6):new T.ConeGeometry(.1,upright?.35:.23,7),fur,side*.2,y+.24,zz-.2)}const jaw=rabbit?null:part(roundedBox(upright?.3:large?.38:.25,.07,upright?.35:.3),fur,0,y-.24,zz+.06);let age=0,attack=0,old=g.position.clone();return {g,heading:0,cueAttack(){attack=.65},update(dt){age+=dt;attack=Math.max(0,attack-dt);const moving=old.distanceToSquared(g.position)>.00001;old.copy(g.position);legs.forEach((l,i)=>l.rotation.x=moving?Math.sin(age*(rabbit?12:7))*(i%2?-.5:.5):0);const strike=attack>0?Math.sin((1-attack/.65)*Math.PI):0;head.rotation.x=strike*.3;if(jaw)jaw.rotation.x=strike*.55;if(upright){legs[0].rotation.x=legs[2].rotation.x=-strike*1.5;fur.emissive.setHex(this.hp<this.maxHp*.4?0x270600:0)}else if(large&&attack>0){legs[1].rotation.x=legs[3].rotation.x=-strike}g.rotation.y=this.heading;if(rabbit)g.position.y=moving?Math.abs(Math.sin(age*12))*.15:0}};
}
export function chapterWildlife({root,mode,free,rand,drop}){
 const actors=[],built=new Set();let clock=0;
 function place(x,z,r=.7){for(let i=0;i<90;i++){const a=i*2.4,d=i*.13,xx=x+Math.cos(a)*d,zz=z+Math.sin(a)*d;if(free(xx,zz,r))return [xx,zz]}return null}
 function spawn(zone,species,index,x,z,exact=false){const p=exact?[x,z]:place(x,z);if(!p)return;const n=beastModel(root(zone),species,...p);Object.assign(n,{id:'c2-fauna-'+zone+'-'+species+'-'+index,zone,species,name:names[species],hp:BEAST_HP[species],maxHp:BEAST_HP[species],home:new T.Vector3(p[0],0,p[1]),target:new T.Vector3(p[0],0,p[1]),cooldown:1,timer:0,windup:0,special:0,generation:0,hit:false,aggro:null,chapterTwo:true,fixedLevel:species==='werewolf'?17:species==='bear'?14:zone==='road'?12:14});actors.push(n);return n}
 function build(zone,x){if(zone==='city'||built.has(zone))return;built.add(zone);const offset=zone==='inn'?64:zone==='manor'?81:52;for(const [species,count] of [['hare',6],['wolf',8],['bear',2]])for(let i=0;i<count;i++)spawn(zone,species,i,x+(i%2?1:-1)*offset,-42-(i*23+(species==='hare'?11:species==='bear'?34:0))%(zone==='inn'?120:155));}
 function visit(zone,x){if(zone!=='city'&&!actors.some(n=>n.zone===zone&&n.species==='werewolf'&&n.hp>0)&&rand()<.8){const old=actors.find(n=>n.zone===zone&&n.species==='werewolf');if(old){old.hp=old.maxHp;old.g.visible=true;old.g.position.copy(old.home);old.generation++;old.aggro=null}else{let pos;for(let i=0;i<120;i++){const xx=x+(rand()-.5)*160,zz=-65-rand()*130;if(free(xx,zz,.8)&&Math.abs(xx-x)>24){pos=[xx,zz];break}}if(!pos)pos=place(x+(zone==='inn'?65:zone==='manor'?81:63),zone==='inn'?-165:-202);if(pos)spawn(zone,'werewolf',0,...pos,true)}}}
 function tick(dt,camera,{onDamage,onSound=()=>{}}){clock+=dt;for(const n of actors){if(n.zone!==mode()||n.hp<=0)continue;const step=statusStep(n,dt),d=Math.hypot(camera.position.x-n.g.position.x,camera.position.z-n.g.position.z);n.cooldown=Math.max(0,n.cooldown-step);n.special=Math.max(0,n.special-step);if(n.species==='hare'){const goal=d<9?n.g.position.clone().add(n.g.position.clone().sub(camera.position).setY(0).normalize().multiplyScalar(4)):n.home;steer(n,goal,d<9?3.6:.6,step,free,()=>true,.25);n.update(step);continue}const sensed=canSense(n,camera,d,n.species==='werewolf'?20:11);if(!n.aggro&&sensed)n.aggro=camera.position.clone();if(n.species==='werewolf'&&n.aggro&&!n.aggroCue){n.aggroCue=true;onSound('werewolf-aggro')}if(!n.aggro)n.aggroCue=false;if(n.aggro&&camera.position.distanceTo(n.aggro)>65)n.aggro=null;if(n.windup>0){n.windup=Math.max(0,n.windup-step);if(!n.windup&&n.aggro){if(n.lunge){for(let j=0;j<9;j++){const dir=camera.position.clone().sub(n.g.position).setY(0).normalize();const x=n.g.position.x+dir.x*.5,z=n.g.position.z+dir.z*.5;if(!free(x,z,.5))break;n.g.position.set(x,0,z)}}const range=n.slam?4.2:3;if(Math.hypot(camera.position.x-n.g.position.x,camera.position.z-n.g.position.z)<range&&[.2,.4,.6,.8].every(t=>free(n.g.position.x+(camera.position.x-n.g.position.x)*t,n.g.position.z+(camera.position.z-n.g.position.z)*t,.05)))onDamage(n.species==='werewolf'?(n.lunge?38:32):n.species==='bear'?(n.slam?36:29):20,'physical',n.id);onSound(n.species==='werewolf'?'werewolf-hit':n.species==='bear'?'bear-hit':'wolf-attack')}}else if(n.aggro){n.heading=Math.atan2(camera.position.x-n.g.position.x,camera.position.z-n.g.position.z);if(!n.root&&d>2.3)steer(n,camera.position,(n.species==='werewolf'?4.3:n.species==='bear'?2.7:3.6)*(n.hp<n.maxHp*.4&&n.species==='werewolf'?1.2:1),step,free,()=>true,.45);if(!n.cooldown&&d<(n.species==='werewolf'?7:3.5)){n.lunge=n.species==='werewolf'&&!n.special;n.slam=n.species==='bear'&&!n.special;n.windup=n.slam?.9:.48;n.cooldown=n.species==='bear'?2.4:1.5;if(n.lunge||n.slam)n.special=9;n.cueAttack()}}else{n.timer-=step;if(n.timer<=0){n.timer=4+rand()*3;const p=place(n.home.x+(rand()-.5)*8,n.home.z+(rand()-.5)*8,.5);if(p)n.target.set(p[0],0,p[1])}steer(n,n.target,.8,step,free,()=>true,.45)}n.update(step)}}
 function killed(n){if(!actors.includes(n))return false;if(n.dropped===n.generation)return true;n.dropped=n.generation;n.g.visible=false;if(n.species==='hare'){if(rand()<.6)drop('carcass',1,n.g.position)}else{drop('gold',n.species==='werewolf'?25:n.species==='bear'?10:3,n.g.position);if(n.species==='wolf'&&rand()<.25)drop('fang',1,n.g.position.clone().add(new T.Vector3(.6,0,0)));if(n.species==='bear')drop('bear_hide',1,n.g.position.clone().add(new T.Vector3(.6,0,0)));if(n.species==='werewolf')drop('werewolf_claw',1,n.g.position.clone().add(new T.Vector3(.6,0,0)))}const group=actors.filter(a=>a.zone===n.zone&&a.species===n.species);if(n.species!=='werewolf'&&group.filter(a=>a.hp<=0).length>=Math.ceil(group.length*.7))for(const a of group)if(a!==n&&a.hp<=0){const p=place(a.home.x+(rand()-.5)*4,a.home.z+(rand()-.5)*4);if(!p)continue;a.hp=a.maxHp;a.g.position.set(p[0],0,p[1]);a.g.visible=true;a.aggro=null;a.generation++;a.windup=0;a.cooldown=1}return true}
 return {actors,build,visit,tick,killed,snapshot:()=>({actors:actors.map(n=>({actor:packActor(n),zone:n.zone,species:n.species,windup:n.windup,special:n.special,lunge:!!n.lunge,slam:!!n.slam})).sort((a,b)=>a.actor.id.localeCompare(b.actor.id))}),restore(s){const ids=new Set((s?.actors||[]).map(n=>n.actor.id));for(let i=actors.length-1;i>=0;i--)if(actors[i].species==='werewolf'&&!ids.has(actors[i].id)){actors[i].g.removeFromParent();actors.splice(i,1)}for(const n of actors){n.hp=n.maxHp;n.g.position.copy(n.home);n.g.visible=true;n.aggro=null;n.generation=0;n.dropped=-1;n.windup=0;n.special=0}for(const a of s?.actors||[]){let n=actors.find(n=>n.id===a.actor.id);if(!n&&a.species==='werewolf')n=spawn(a.zone,a.species,0,a.actor.home[0],a.actor.home[2],true);if(!n)continue;restoreActor(n,a.actor);Object.assign(n,{windup:a.windup,special:a.special,lunge:a.lunge,slam:a.slam,aggroCue:!!n.aggro,dropped:n.hp<=0?n.generation:-1})}},reset(){for(const n of actors){n.aggro=null;n.windup=0;n.aggroCue=false;n.stun=n.slow=n.root=0}}};
}
